#![allow(unused)]
use verus::prelude::*;

verus! {

    /// Given a non-empty list of 32-bit signed integers,
    /// returns the maximum value in the list.
    ///
    /// Specification:
    ///   - The input length is strictly greater than 0.
    ///   - The result is equal to the value at some index of the input.
    ///   - Every element in the list is less than or equal to the result.
    pub proof fn max_of_list(lst: Vec<i32>) -> (result: i32)
        requires
            lst.len() > 0
        ensures
            // result equals some element in the list
            (exists |j: usize| j < lst.len() && result == lst[j])
        ensures
            // every element is <= result
            forall |k: usize| k < lst.len() ==> lst[k] <= result
    {
        // We'll do a standard linear scan, maintaining an index `i`
        // and `current_max` = max of lst[0..i).
        let mut i: usize = 1;
        let mut current_max: i32 = lst[0];

        // Loop until we've processed all elements.
        while i < lst.len() {
            invariant
                // `i` never exceeds the length of the list
                i <= lst.len();
            invariant
                // For all seen positions < i, those elements are <= current_max
                forall |k: usize| k < i ==> lst[k] <= current_max;
            invariant
                // There is some j < i for which current_max == lst[j]
                exists |j: usize| j < i && current_max == lst[j];
            decreases
                // We make progress by increasing i
                lst.len() - i
            ;
            
            let v = lst[i];
            if v > current_max {
                current_max = v;
            }
            i += 1;
        }

        // At this point, i == lst.len(), so current_max is the max over the whole list.
        result = current_max;
    }

}